<p>or try modify your code this way:</p>

<pre><code>function list_all($lang, $limit = FALSE, $offset = FALSE)
{

    $this-&gt;db-&gt;select('*');
    $this-&gt;db-&gt;select("DATE_FORMAT(datetime, '%d.%m.%Y à %H:%i:%s') AS datetime");

